import pytest

from bedrock_protocol import v729, v748, v800, v818, v2168

# generated by gophertunnel 3e16382:
# &packet.SetMovementAuthority{MovementType: 0}
LEGACY_CLIENT_AUTHORITATIVE = bytes.fromhex("00")

# generated by gophertunnel 3e16382:
# &packet.SetMovementAuthority{MovementType: 1}
CLIENT_AUTHORITATIVE = bytes.fromhex("01")

# generated by gophertunnel 3e16382:
# &packet.SetMovementAuthority{MovementType: 2}
SERVER_AUTHORITATIVE = bytes.fromhex("02")

MODE = v748.ServerAuthMovementMode

GOLDENS = [
    pytest.param(
        v748.SetMovementAuthorityPacket(new_auth_movement_mode=MODE.LEGACY_CLIENT_AUTHORITATIVE_V1_DEPRECATED),
        LEGACY_CLIENT_AUTHORITATIVE,
        id="legacy-client-authoritative",
    ),
    pytest.param(
        v748.SetMovementAuthorityPacket(new_auth_movement_mode=MODE.CLIENT_AUTHORITATIVE_V2),
        CLIENT_AUTHORITATIVE,
        id="client-authoritative",
    ),
    pytest.param(
        v748.SetMovementAuthorityPacket(new_auth_movement_mode=MODE.SERVER_AUTHORITATIVE_V3),
        SERVER_AUTHORITATIVE,
        id="server-authoritative",
    ),
]


@pytest.mark.parametrize("version", [v748, v800], ids=lambda version: version.__name__.rpartition(".")[2])
def test_set_movement_authority_is_packet_319(version):
    assert version.PACKETS[319] is version.SetMovementAuthorityPacket


@pytest.mark.parametrize("version", [v729, v818, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_set_movement_authority_is_not_a_packet_319_outside_748_to_800(version):
    assert 319 not in version.PACKETS


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_movement_authority_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_movement_authority_decodes_from_its_golden(packet, golden):
    assert v748.SetMovementAuthorityPacket.from_bytes(golden) == packet
